update hvps_trans
set biz_sts  = #{hvpsTransDO.bizSts, jdbcType=VARCHAR},
    biz_prc_cd = #{hvpsTransDO.bizPrcCd, jdbcType=VARCHAR},
    biz_prc_inf = #{hvpsTransDO.bizPrcInf, jdbcType=VARCHAR},
    sttlm_dt = #{hvpsTransDO.sttlmDt, jdbcType=VARCHAR},
